// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    DEP_BANK c;
    function setUp() public { c = new DEP_BANK(); }
    function testFuzz_property(uint256 firstVal, uint256 secondVal) public {
        vm.assume(secondVal != firstVal);
        // set MinSum before initialization: always succeeds in both versions
        c.SetMinSum(firstVal);
        require(c.MinSum() == firstVal, "setup");
        // freeze the configuration
        c.Initialized();
        // after initialization, SetMinSum must not change MinSum in the reference
        // (it reverts there; the mutant lets it succeed and overwrite)
        try c.SetMinSum(secondVal) { /* mutant path: succeeds */ } catch { /* reference path: reverts */ }
        assertTrue(c.MinSum() == firstVal);
    }
}
